const DEMO_PEOPLE=[{id:'d-alex',first_name:'Alex',last_name:'Rivera',role:'installer',telegram_id:'123456789'},{id:'d-mary',first_name:'Kate',last_name:'Manager',role:'pm',telegram_id:'234567890'}];
function stageSeed(id,key,title,subtitle,ic,cats,labels,done=false){return{id,stage_key:key,title,subtitle,icon:ic,guide:'Capture photos and complete the checklist before submitting.',media_requirements:cats,completion:{done,missingMedia:done?[]:cats.filter(x=>x.required).map(x=>x.label),missingChecks:done?[]:labels.filter(x=>x.required).map(x=>x.label)},checks:labels};}
const cat=(key,label,kind='image',required=true)=>({key,label,kind,required});const ck=(key,label,required=true)=>({id:`demo-${key}`,stage_id:'',label,required,result_status:'pending'});
function demoProject(){
 const proj={id:'demo-project',title:'Miami Residence',code:'WP-26-1042',address:'Brickell, Miami, FL',client_name:'Private Residence',project_type:'installation',scheduled_for:new Date().toISOString().slice(0,10),status:'active',pm_id:'demo-me',notes:'Luxury wall panels and concealed doors.'};
 const s=[stageSeed('s1','preflight','Before Departure','Site and equipment ready','clipboard',[],[ck('tools','Tools and materials ready'),ck('plans','Approved plans checked')],true),stageSeed('s2','before','Arrival & Before','Record original condition','camera',[cat('flags','Installed flags'),cat('overview','Room overview'),cat('floor','Floor'),cat('before_video','BEFORE video','video')],[ck('arrived','Address confirmed')],true),stageSeed('s3','protection','Site Protection','Protect property','shield',[cat('protected_floor','Protected floor')],[ck('protect','Floor and furniture protected')],true),stageSeed('s4','progress','Installation Progress','Document work','wrench',[cat('progress','Work in progress')],[ck('quality','No unapproved changes')]),stageSeed('s5','installed','After Installation','Final installation photos','layers',[cat('finished_overview','Completed room'),cat('after_video','AFTER video','video')],[ck('finished','Installation checked')]),stageSeed('s6','cleanup','Cleanup & Final Photos','Before and after cleaning','sparkles',[cat('pre_cleanup','Before cleanup'),cat('post_cleanup','After cleanup')],[ck('clean','Site cleaned')]),stageSeed('s7','handover','Quality & Handover','Client sign-off','badge',[],[ck('client','Client walkthrough')])];
 const checks=s.flatMap(x=>x.checks.map(c=>({...c,stage_id:x.id,result_status:x.completion.done?'done':'pending'})));
 const svg=(label)=>`data:image/svg+xml;charset=utf-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 450"><rect width="600" height="450" fill="#e9e1fc"/><path d="M0 300L250 130 600 360V450H0" fill="#d1c3fa"/><circle cx="460" cy="120" r="58" fill="#b5a4ed"/><text x="40" y="410" fill="#7055b7" font-size="35" font-family="sans-serif">${label}</text></svg>`)}`;
 const media=[...s[1].media_requirements,...s[2].media_requirements].map((r,i)=>({id:`demo-photo-${i}`,stage_id:i<s[1].media_requirements.length?'s2':'s3',category_key:r.key,kind:r.kind,file_name:`${r.key}.${r.kind==='video'?'mp4':'jpg'}`,url:r.kind==='video'?'':svg(r.label)}));
 return {project:proj,stages:s,checks,media,days:[],issues:[],members:[],people:DEMO_PEOPLE,exceptions:[],confirmation:null,dayChecks:[{key:'tools_collected',label:'Tools collected'},{key:'site_tidy',label:'Site tidy'},{key:'no_hazards',label:'No hazards'},{key:'pm_updated',label:'PM informed'}]};
}
